'use strict';

// MODULES //

var isnan = require( '@stdlib/math-base-assert-is-nan' );
var incrmvariance = require( '@stdlib/stats-incr-mvariance' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving unbiased sample variance, ignoring `NaN` values.
*
* @param {PositiveInteger} W - window size
* @param {number} [mean] - mean value
* @throws {TypeError} first argument must be a positive integer
* @throws {TypeError} second argument must be a number
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmvariance( 3 );
*
* var s2 = accumulator();
* // returns null
*
* s2 = accumulator( 2.0 );
* // returns 0.0
*
* s2 = accumulator( -5.0 );
* // returns 24.5
*
* s2 = accumulator( NaN );
* // returns 24.5
*
* s2 = accumulator( 3.0 );
* // returns 19.0
*
* s2 = accumulator( 5.0 );
* // returns 28.0
*
* s2 = accumulator();
* // returns 28.0
*
* @example
* var accumulator = incrnanmvariance( 3, -2.0 );
*/
function incrnanmvariance( W, mean ) {
	var acc;
	if ( arguments.length > 1 ) {
		acc = incrmvariance( W, mean );
	} else {
		acc = incrmvariance( W );
	}
	return accumulator;

	/**
	* If provided a value, the accumulator function returns an updated unbiased sample variance. If provided `NaN` or no value, the accumulator function returns the current unbiased sample variance.
	*
	* @private
	* @param {number} [x] - input value
	* @returns {(number|null)} unbiased sample variance or null
	*/
	function accumulator( x ) {
		if ( arguments.length === 0 || isnan( x ) ) {
			return acc();
		}
		return acc( x );
	}
}


// EXPORTS //

module.exports = incrnanmvariance;
